def economic_model():
    scenarios = {"CONSERVATIVE": (120,2,20,25,30,8,800,600), "BASE": (165,3,22,30,35,10,1200,900), "UPSIDE": (210,4,24,38,40,12,1800,1400)}
    out={}
    for name,(ticket,jobs,days,var,labor,travel,fixed,marketing) in scenarios.items():
        monthly_jobs=jobs*days; revenue=ticket*monthly_jobs; costs=(var+labor+travel)*monthly_jobs+fixed+marketing
        gross_profit=revenue-(var*monthly_jobs); contribution=revenue-((var+labor+travel)*monthly_jobs)
        break_even=max(1, int((fixed+marketing)/(ticket-var-labor-travel))+1)
        out[name]={"average_ticket":ticket,"jobs_per_day":jobs,"working_days":days,"monthly_jobs":monthly_jobs,"monthly_revenue":revenue,"gross_profit":gross_profit,"gross_margin":round(gross_profit/revenue,4),"contribution_margin":round(contribution/revenue,4),"break_even_jobs_per_month":break_even,"estimated_cac_payback_months":"UNPROVEN","total_modeled_costs":costs}
    memberships=[{"name":"monthly maintenance","price":99,"visits_per_month":1,"jobs_per_customer":1,"capacity_note":"fits one monthly slot; route density required"},{"name":"biweekly maintenance","price":179,"visits_per_month":2,"jobs_per_customer":2,"capacity_note":"higher retention potential but consumes two capacity slots"},{"name":"multi-vehicle household","price":299,"visits_per_month":2,"jobs_per_customer":2,"capacity_note":"higher ticket; vehicle count and service scope must be validated"},{"name":"fleet/business package","price":250,"visits_per_month":2,"jobs_per_customer":2,"capacity_note":"requires route density and service-level validation"}]
    return {"scenarios":out,"memberships":memberships,"assumptions":{"source_backed_inputs":["published competitor prices and membership structures"],"model_assumptions":["scenario tickets, capacity, cost inputs are explicit test assumptions"],"user_test_assumptions":["Phoenix-area validation is the scoped test market"]}}

def _append(collection, row): persistence.append_record(collection,row); return row
def _receipt(loop_id, stage, refs, status="PASS"):
    row={"receipt_id":persistence.new_id("bizrcpt"),"loop_id":loop_id,"stage":stage,"status":status,"evidence_refs":refs,"result_fingerprint":_fp({"stage":stage,"refs":refs}),"created_at":_now()}
    return _append("business_receipts",row)
def _save_order(order): return _append("work_orders",order)

