    alpha=build_work_order(goal_id=goal_id,work_type="research",owner_specialist="ALPHA",loop_id=loop_id,inputs={"idea_id":idea_id,"question":"commercial viability of a mobile detailing business","research_scope":["demand proxies","competitors","pricing","membership","operations","risks"]},cost_budget={"max_usd":0},retry_budget={"max_attempts":2})
